/* Authentic Roblox Subspace Tripmine (11999247) client data, mesh decoder, audio cues, & Hot Pink + Sparkles blast renderer.
 * Official public Roblox asset bytes are treated strictly as data; embedded Lua is never executed. */
(() => {
  'use strict';

  const MESH_B64 = '';
  const ICON_URL = 'assets/subspace-icon-11987521.png';
  const TEXTURE_URL = 'assets/subspace-tex-11954766.png';
  const CALIBRATE_SOUND_URL = 'assets/subspace-calibrate-11956590.ogg';
  const PULSE_SOUND_URL = 'assets/subspace-dundun-11984254.ogg';
  const EXPLOSION_SOUND_URL = 'assets/subspace-explosion-11984351.ogg';
  const HOT_PINK = Object.freeze([1, 0, 0.75, 1]); // BrickColor 1032

  let parsedGeometry = null;
  function geometry() {
    if (parsedGeometry) return parsedGeometry;
    const binary = (window.atob || atob)(MESH_B64);
    const bytes = Uint8Array.from(binary, ch => ch.charCodeAt(0));
    const source = new TextDecoder().decode(bytes);
    const lines = source.split(/\r?\n/);
    if (lines[0] !== 'version 1.00') throw new Error('Subspace mesh version mismatch');
    const faceCount = Number(lines[1]);
    const records = [...lines.slice(2).join('\n').matchAll(/\[([^\]]+)\]/g)];
    if (!Number.isInteger(faceCount) || faceCount !== 280 || records.length !== faceCount * 9) {
      throw new Error('Subspace mesh record count mismatch');
    }
    const vectors = records.map(m => m[1].split(',').map(Number));
    const vertices = [], uvs = [];
    // Source SpecialMesh Scale is [0.7, 0.7, 0.7]; v1.00 half-unit conversion is 0.5 -> 0.35.
    const scale = 0.35;
    for (let face = 0; face < faceCount; face++) {
      for (let vertex = 0; vertex < 3; vertex++) {
        const i = face * 9 + vertex * 3;
        const p = vectors[i], n = vectors[i + 1], uv = vectors[i + 2];
        vertices.push(p[0] * scale, p[1] * scale, p[2] * scale, n[0], n[1], n[2]);
        uvs.push(uv[0], 1 - uv[1]);
      }
    }
    parsedGeometry = Object.freeze({
      vertices: new Float32Array(vertices),
      uvs: new Float32Array(uvs),
      count: vertices.length / 6,
      vertexCount: vertices.length / 6,
      sourceAssetId: 11954776
    });
    return parsedGeometry;
  }

  const grip = Object.freeze({
    position: [-0.5, 0, 0],
    rotation: [0, 0, -1, 0, 1, 0, 1, 0, 0]
  });

  window.UploadedAssetIcons = Object.freeze({ ...(window.UploadedAssetIcons || {}), subspace: ICON_URL });

  window.SubspaceTripmineData = Object.freeze({
    toolName: 'Subspace Tripmine',
    assetId: 11999247,
    iconAssetId: 11987521,
    meshAssetId: 11954776,
    textureAssetId: 11954766,
    iconData: ICON_URL,
    textureData: TEXTURE_URL,
    calibrateSound: CALIBRATE_SOUND_URL,
    pulseSound: PULSE_SOUND_URL,
    explosionSound: EXPLOSION_SOUND_URL,
    hotPink: HOT_PINK,
    cooldownMs: 3000,
    blastRadius: 16,
    grip,
    geometry
  });

  function drawFallback(frame, boxFrame, A, alpha = 1) {
    if (alpha <= 0.01) return;
    const cCore = [1, 0.08, 0.72, alpha];
    const cCage = [0.22, 0.18, 0.25, alpha];
    boxFrame([0.75, 0.75, 0.75], frame, cCore);
    boxFrame([1.65, 0.22, 0.22], frame, cCage);
    boxFrame([0.22, 1.65, 0.22], frame, cCage);
    boxFrame([0.22, 0.22, 1.65], frame, cCage);
  }

  function createEffectsManager({ playSound } = {}) {
    const seenMines = new Map();
    const bursts = [];
    let readyAtSec = 0;
    let resolveSparkleTarget = null;

    function markActivated(nowSec) {
      readyAtSec = nowSec + 3;
    }
    function isReady(nowSec) {
      return nowSec >= readyAtSec;
    }
    function readyAt() {
      return readyAtSec;
    }

    function stopCalibrate(prev) {
      const a = prev && prev.calibrateAudio;
      if (!a) return;
      prev.calibrateAudio = null;
      try {
        a.loop = false;
        a.pause?.();
        if (typeof Event === 'function') a.dispatchEvent?.(new Event('ended'));
      } catch {}
    }

    function syncObjects(objects) {
      const activeIds = new Set();
      const nowMs = Date.now();
      for (const o of objects || []) {
        if (!o || o.kind !== 'subspace') continue;
        activeIds.add(o.id);
        const st = o.stage || 'calibrating';
        let prev = seenMines.get(o.id);
        if (!prev) {
          prev = { stage: st, pulseUntil: 0, calibrateAudio: null, retryAt: 0 };
          seenMines.set(o.id, prev);
        }
        if (st === 'calibrating' || st === 'arming') {
          if (prev.calibrateAudio && prev.calibrateAudio.paused === true) {
            stopCalibrate(prev);
          }
          if (!prev.calibrateAudio && Array.isArray(o.pos) && nowMs >= (prev.retryAt || 0)) {
            prev.retryAt = nowMs + 500;
            prev.calibrateAudio = playSound?.(CALIBRATE_SOUND_URL, o.pos) || null;
            if (prev.calibrateAudio) prev.calibrateAudio.loop = true;
          }
        } else if (prev.calibrateAudio) {
          stopCalibrate(prev);
        }
        if ((o.pulseUntil || 0) > (prev.pulseUntil || 0) && (o.stage === 'pulse' || (o.alpha > 0.05 && o.stage !== 'calibrating'))) {
          prev.pulseUntil = o.pulseUntil;
          if (Array.isArray(o.pos)) playSound?.(PULSE_SOUND_URL, o.pos);
        }
        prev.stage = st;
      }
      for (const id of [...seenMines.keys()]) {
        if (!activeIds.has(id)) { stopCalibrate(seenMines.get(id)); seenMines.delete(id); }
      }
    }

    const paintEvents = [];
    function clearEffects() { bursts.length = 0; paintEvents.length = 0; for (const st of seenMines.values()) stopCalibrate(st); seenMines.clear(); }
    function setSparkleResolver(resolver) { resolveSparkleTarget = typeof resolver === 'function' ? resolver : null; }

    function addPaintEvent(event, nowSec) {
      if (!event || typeof event.id !== 'string' || !Number.isFinite(event.expiresAt)) return false;
      const parts = Array.isArray(event.parts) ? event.parts.slice(0, 64).filter(p => p && typeof p.id === 'string' && Array.isArray(p.center) && Array.isArray(p.size)) : [];
      const cells = Array.isArray(event.cells) ? event.cells.slice(0, 128).filter(c => c && Array.isArray(c.center) && Array.isArray(c.size)) : [];
      if (!parts.length && !cells.length) return false;
      const old = paintEvents.findIndex(e => e.id === event.id); if (old >= 0) paintEvents.splice(old, 1);
      if (paintEvents.length >= 24) paintEvents.shift();
      paintEvents.push({ id: event.id, expiresAt: event.expiresAt, parts, cells, startedAt: nowSec }); return true;
    }
    function syncPaint(events, nowSec) { if (!Array.isArray(events)) return; for (const e of events.slice(0, 24)) addPaintEvent(e, nowSec); }
    function drawPaint(nowSec, boxFrame, A) {
      const nowMs = Date.now(); let drawn = 0;
      for (let i = paintEvents.length - 1; i >= 0; i--) {
        const ev = paintEvents[i]; if (nowMs >= ev.expiresAt) { paintEvents.splice(i, 1); continue; }
        const fade = Math.min(1, (ev.expiresAt - nowMs) / 10000);
        for (const cell of ev.cells) { if (drawn >= 512) break; const s = cell.size; const frame = A.yawFrame(cell.center[0], cell.center[1] + s[1] / 2 + .035, cell.center[2], 0); boxFrame([Math.max(.2, s[0] * .92), .06, Math.max(.2, s[2] * .92)], frame, [1, .12, .72, .82 * fade]); drawn++; }
        for (const part of ev.parts) { if (drawn >= 512) break; const resolved = resolveSparkleTarget?.(part); if (!resolved) continue; const c = resolved.center, s = resolved.size || part.size; for (let k = 0; k < 6 && drawn < 512; k++) { const phase = k * 2.399 + part.id.length * .37; const face = k % 3; const ox = Math.sin(phase) * .32, oz = Math.cos(phase) * .32; let center = c.slice(), size = [Math.min(2.4, s[0] * .38), Math.min(2.4, s[1] * .38), .07]; if (face === 0) { center[1] += s[1] / 2 + .04; size = [size[0], .07, size[1]]; } else if (face === 1) { center[0] += s[0] / 2 + .04; size = [.07, size[1], size[0]]; } else { center[2] += s[2] / 2 + .04; } center[0] += ox * s[0]; center[2] += oz * s[2]; boxFrame(size, A.yawFrame(center[0], center[1], center[2], phase), [1, .12, .72, .82 * fade]); drawn++; } }
      }
    }
    function onBlast(detail, nowSec) {
      if (!detail || detail.kind !== 'subspace') return false;
      const center = [Number(detail.x) || 0, Number(detail.y) || 0, Number(detail.z) || 0];
      playSound?.(EXPLOSION_SOUND_URL, center);
      const authoritativeParts = Array.isArray(detail.sparkleParts);
      const targets = authoritativeParts ? detail.sparkleParts.slice(0, 64).filter(p => p && typeof p.id === 'string' && Array.isArray(p.center) && p.center.length === 3 && p.center.every(Number.isFinite) && Array.isArray(p.size) && p.size.length === 3 && p.size.every(Number.isFinite)) : [];
      const sparks = [];
      if (authoritativeParts) {
        for (const target of targets) for (let i = 0; i < 6; i++) {
          const phase = i * 2.399 + target.id.length * 0.37;
          sparks.push({ target, ox: Math.sin(phase) * 0.38, oy: Math.cos(phase * 1.7) * 0.35, oz: Math.cos(phase) * 0.38, vy: 0.7 + (i % 3) * 0.2, phase, size: 0.18 + (i % 3) * 0.05 });
        }
      } else {
        for (let i = 0; i < 36; i++) {
          const ang = (i / 36) * Math.PI * 2 + (i % 5) * 0.37;
          const elev = ((i * 7) % 11) / 11 * 0.85 + 0.1;
          const dist = 1.2 + ((i * 13) % 15);
          sparks.push({ ox: Math.cos(ang) * dist * (1 - elev * 0.45), oy: (i % 4) * 0.55, oz: Math.sin(ang) * dist * (1 - elev * 0.45), vy: 1.8 + (i % 6) * 0.65, phase: i * 0.91, size: 0.24 + (i % 3) * 0.09 });
        }
      }
      if (detail.paintEvent) addPaintEvent(detail.paintEvent, nowSec);
      if (bursts.length >= 16) bursts.shift();
      bursts.push({ center, startedAt: nowSec, uncloakUntil: nowSec + 0.3, expiresAt: nowSec + 5.0, sparks });
      return true;
    }

    function drawBursts(nowSec, drawMineFn, boxFrame, A) {
      drawPaint(nowSec, boxFrame, A);
      for (let i = bursts.length - 1; i >= 0; i--) {
        const b = bursts[i];
        if (nowSec >= b.expiresAt) { bursts.splice(i, 1); continue; }
        const elapsed = Math.max(0, nowSec - b.startedAt);
        if (nowSec < b.uncloakUntil) {
          const fade = Math.max(0, 1 - elapsed / 0.3);
          drawMineFn?.(b.center, fade);
        }
        const lifeLeft = Math.min(1, (b.expiresAt - nowSec) / 1.0);
        for (const s of b.sparks) {
          const twinkle = 0.5 + 0.5 * Math.sin(elapsed * 14 + s.phase);
          if (twinkle < 0.22) continue;
          let anchor = b.center, size = [2, 2, 2];
          if (s.target) {
            const resolved = resolveSparkleTarget?.(s.target);
            if (!resolved) continue;
            anchor = resolved.center; size = resolved.size || s.target.size;
          }
          const px = anchor[0] + s.ox * size[0];
          const py = anchor[1] + s.oy * size[1] + Math.sin(elapsed * 2.4 + s.phase) * 0.25 + (elapsed % 1.6) * s.vy * 0.3;
          const pz = anchor[2] + s.oz * size[2];
          const sz = s.size * (0.65 + 0.55 * twinkle) * lifeLeft;
          const frame = A.yawFrame(px, py, pz, elapsed * 3 + s.phase);
          boxFrame([sz, sz, sz], frame, twinkle > 0.72 ? [1, 0.55, 0.95, 1] : [1, 0, 0.75, 1]);
        }
      }
    }

    return Object.freeze({ markActivated, isReady, readyAt, syncObjects, onBlast, drawBursts, setSparkleResolver, clearEffects, addPaintEvent, syncPaint, getPaintState: () => paintEvents.map(e => ({ id: e.id, expiresAt: e.expiresAt, parts: e.parts.length, cells: e.cells.length })) });
  }

  window.SubspaceTripmine = Object.freeze({
    data: window.SubspaceTripmineData,
    drawFallback,
    createEffectsManager
  });
})();
